# application-l093.yml
arranque:
  sufijo-libreria: "L093ASIN"   # P091 usa L091ASIN

// ---------------------------------------------------------------------------
String resuelveVersionTimeOut(String usercode) {
    return ctlvers.dameTitulo(usercode + "." + props.sufijoLibreria())   // DAME_TIT(E_MSG, TITULO)
            .orElseGet(() -> {
                log.warn("ERROR AL LLAMAR A CONTROL DE VERSIONES");
                return props.tituloTimeOutPorDefecto();
            });
}

