# application-l093.yml
arranque:
  prefijo-volcado: "S500/LIST/P093"   # P091: S500/LIST/P091

// ---------------------------------------------------------------------------
Path rutaVolcado(int csi, LocalTime arranque) {   // {prefijo}/{csi}00/R000/{hora}.
    return Path.of(props.prefijoVolcado(), "%02d00".formatted(csi), "R000",
                   arranque.format(DateTimeFormatter.ofPattern("HHmmss")));
}

