/** Mismo puerto que P091: la lógica real vive en TIME_OUT (L091). */
public interface EnvioCancelacionesPort {
    void enviaCancelaciones(ComsCanal canal);   // ENVIA_CANCELACIONES(COMS_IN, COMS_OUT, IN_EV, TSK_EV)
}

@Bean
IntegrationFlow cancelacionesEnLinea(ComsInboundAdapter coms) {   // ENABLE(COMSINHDR, "ONLINE")
    return IntegrationFlow.from(coms).channel("cancelaciones.entrada").get();
}
// DELINKLIBRARY(CTLVER) / DELINKLIBRARY(SHELL): los clientes de arranque no se vuelven a usar.

@Component
@Profile("l093")
@RequiredArgsConstructor
public class ArranqueCancelacionesRunner implements ApplicationRunner {

    private final EnvioCancelacionesPort envio;
    private final ComsCanal canal;

    @Override
    public void run(ApplicationArguments args) {
        inicia();                              // INICIA;
        envio.enviaCancelaciones(canal);       // no regresa mientras el servicio esté activo
    }
}
